create temporary view user_exp_${grass_region_without_quote} as
select
    user_id
    ,exp_group_id
from
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and is_assignment_log = 1
    and scene_id in (142, 368) -- daily_discover_main: 142; cart_unify: 368
;

--sql_divide_splitter--
create temporary view user_item_raw_${grass_region_without_quote} as
select
    user_id
    ,case when is_ads = true then 'true' else 'false' end as is_ads
    ,case
        when array_contains(scenario_tags, 'dpm module Daily Discover business line Homepage') then 'DD'
        when exists(scenario_tags, x -> x like 'dpm reporting object post purchase % business line Rcmd') then 'PP'
    end as scene_type
    ,omni_scenario_imp_cnt
    ,item_llm_cluster_id
    ,array_distinct(split(queues, ',')) as queues
from
    srdi_mart.dwm_sr_data_warehouse_platform_user_item
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation = 'omni_impression'
    and (
        array_contains(scenario_tags, 'dpm module Daily Discover business line Homepage')
        or exists(scenario_tags, x -> x like 'dpm reporting object post purchase % business line Rcmd')
    )
    and user_id > 0
    and if(split(feature_detail, '-')[2] IS NOT NULL, split(feature_detail, '-')[2], split(feature_detail, '-')[1]) in ('item', 'item_mix_feed_card')
    and omni_scenario_imp_cnt > 0
    and queues is not null
    and queues not in ('', ',')
;

--sql_divide_splitter--
create temporary view user_cluster_agg_${grass_region_without_quote} as
select
    user_id
    ,scene_type
    ,queues
    ,item_llm_cluster_id
    ,is_ads
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
from
    user_item_raw_${grass_region_without_quote}
group by 1, 2, 3, 4, 5
;

--sql_divide_splitter--
create temporary view user_cluster_exp_${grass_region_without_quote} as
select
    t1.user_id
    ,is_ads
    ,scene_type
    ,queues
    ,item_llm_cluster_id
    ,exp_group_id
    ,omni_scenario_imp_cnt
from
    user_cluster_agg_${grass_region_without_quote} as t1
inner join
    user_exp_${grass_region_without_quote} as t2
on t1.user_id = t2.user_id
;

--sql_divide_splitter--
create temporary view user_level_explode_queue_${grass_region_without_quote} as
select
    user_id
    ,exp_group_id
    ,scene_type
    ,recall_queue
    ,'Aggregated Organic Item' as card_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,max(case when omni_scenario_imp_cnt > 0 then true else false end) as has_imp
    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
from
    user_cluster_exp_${grass_region_without_quote}
    lateral view explode(queues) as recall_queue
where
    is_ads != 'true'
group by 1, 2, 3, 4

union all
select
    user_id
    ,exp_group_id
    ,scene_type
    ,recall_queue
    ,'Aggregated Item' as card_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,max(case when omni_scenario_imp_cnt > 0 then true else false end) as has_imp
    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
from
    user_cluster_exp_${grass_region_without_quote}
    lateral view explode(queues) as recall_queue
group by 1, 2, 3, 4
;

