    user_id
    ,exp_group_id
    ,scene_type
    ,shuffle(queues)[0] as recall_queue
    ,'Aggregated Item' as card_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,max(case when omni_scenario_imp_cnt > 0 then true else false end) as has_imp
    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
from
    user_cluster_exp_${grass_region_without_quote}
group by 1, 2, 3, 4
;

--sql_divide_splitter--
create temporary view explode_queue_metrics_${grass_region_without_quote} as
select
    scene_type
    ,card_type
    ,exp_group_id
    ,recall_queue

    ,sum(omni_scenario_imp_cnt) as imp_cnt
    ,count(distinct if(has_imp, user_id, null)) as imp_uu
    ,sum(imp_llm_cat_count_per_uu) as imp_llm_cat_cnt
from
    user_level_explode_queue_${grass_region_without_quote}
group by 1, 2, 3, 4
;

--sql_divide_splitter--
create temporary view random_queue_metrics_${grass_region_without_quote} as
select
    scene_type
    ,card_type
    ,exp_group_id
    ,recall_queue

    ,sum(omni_scenario_imp_cnt) as imp_cnt_random
    ,count(distinct if(has_imp, user_id, null)) as imp_uu_random
    ,sum(imp_llm_cat_count_per_uu) as imp_llm_cat_cnt_random
from
    user_level_random_queue_${grass_region_without_quote}
group by 1, 2, 3, 4
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_exp_explode_queues_level_diversity_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})

select
    t1.scene_type
    ,t1.card_type
    ,t1.exp_group_id
    ,t1.recall_queue

    ,imp_cnt
    ,imp_uu
    ,imp_llm_cat_cnt
    ,coalesce(imp_cnt_random, 0) as imp_cnt_random
    ,coalesce(imp_uu_random, 0) as imp_uu_random
    ,coalesce(imp_llm_cat_cnt_random, 0) as imp_llm_cat_cnt_random
from
    explode_queue_metrics_${grass_region_without_quote} t1
left join
    random_queue_metrics_${grass_region_without_quote} t2
on
    t1.scene_type = t2.scene_type
    and t1.card_type = t2.card_type
    and t1.exp_group_id = t2.exp_group_id
    and t1.recall_queue = t2.recall_queue
;
